CREATE TABLE IF NOT EXISTS students ("marital_status" DOUBLE PRECISION, "application_mode" DOUBLE PRECISION, "application_order" DOUBLE PRECISION, "course" DOUBLE PRECISION, "daytime_evening_attendance" DOUBLE PRECISION, "previous_qualification" DOUBLE PRECISION, "previous_qualification_grade" DOUBLE PRECISION, "nacionality" DOUBLE PRECISION, "mothers_qualification" DOUBLE PRECISION, "fathers_qualification" DOUBLE PRECISION, "mothers_occupation" DOUBLE PRECISION, "fathers_occupation" DOUBLE PRECISION, "admission_grade" DOUBLE PRECISION, "displaced" DOUBLE PRECISION, "educational_special_needs" DOUBLE PRECISION, "debtor" DOUBLE PRECISION, "tuition_fees_up_to_date" DOUBLE PRECISION, "gender" DOUBLE PRECISION, "scholarship_holder" DOUBLE PRECISION, "age_at_enrollment" DOUBLE PRECISION, "international" DOUBLE PRECISION, "curricular_units_1st_sem_credited" DOUBLE PRECISION, "curricular_units_1st_sem_enrolled" DOUBLE PRECISION, "curricular_units_1st_sem_evaluations" DOUBLE PRECISION, "curricular_units_1st_sem_approved" DOUBLE PRECISION, "curricular_units_1st_sem_grade" DOUBLE PRECISION, "curricular_units_1st_sem_without_evaluations" DOUBLE PRECISION, "curricular_units_2nd_sem_credited" DOUBLE PRECISION, "curricular_units_2nd_sem_enrolled" DOUBLE PRECISION, "curricular_units_2nd_sem_evaluations" DOUBLE PRECISION, "curricular_units_2nd_sem_approved" DOUBLE PRECISION, "curricular_units_2nd_sem_grade" DOUBLE PRECISION, "curricular_units_2nd_sem_without_evaluations" DOUBLE PRECISION, "unemployment_rate" DOUBLE PRECISION, "inflation_rate" DOUBLE PRECISION, "gdp" DOUBLE PRECISION, "status" TEXT);
TRUNCATE students;
COPY students FROM '/tmp/students.csv' WITH (FORMAT CSV, HEADER TRUE, DELIMITER ';', ENCODING 'UTF8');
